<script setup lang="ts">
import {nextTick,ref,shallowRef,watch,onBeforeUnmount} from 'vue';
import type {Input,Output} from '../../shared/protocol/registry';
import {recycleNative} from '../services';
const effectLabels:Record<string,string>={learning_cards:'卡片身份',learning_content_versions:'正文版本',learning_study_cycles:'学习周期',learning_review_events:'复盘历史',learning_card_drafts:'卡片草稿',learning_published_modes:'已发布模式',scheduling:'FSRS调度',schedule_events:'排期历史',study_sessions:'复盘页面',settings:'正文、草稿与关联',recycle_batches:'回收及下级恢复记录',protocol_receipts:'操作回执',audits:'操作记录',decks:'卡片集',knowledge:'知识点',question_knowledge:'错题知识关联',memory_knowledge:'记忆知识关联',questions:'原错题内容',memory_cards:'原记忆内容',attempts:'原错题历史',memory_reviews:'原记忆历史',assets:'附件关联',materials:'专属材料',saved_filters:'筛选配置',relations:'知识点关系',analyses:'知识点分析',knowledge_keys:'知识存档关联',knowledge_archives:'知识存档',knowledge_specialty_prefs:'知识点学习配置'};
const props=defineProps<{input:Input<'recycle.native.preview'>;disabled?:boolean}>(),emit=defineEmits<{changed:[]}>();
const view=shallowRef<Output<'recycle.native.purge.preview'>>(),busy=ref(false),error=ref(''),dialog=ref<HTMLDialogElement>(),confirmed=ref(false),subtree=ref(false);
let generation=0,origin:HTMLElement|null=null;
const pending=shallowRef<{payload:Input<'recycle.native.purge'>;requestId:string}|null>(null);
function canClose(){return !busy.value&&!pending.value;}
function close(){if(!canClose())return;generation++;dialog.value?.close();view.value=undefined;error.value='';confirmed.value=false;origin?.focus();}
async function preview(){if(pending.value)return;const current=++generation;busy.value=true;error.value='';view.value=undefined;confirmed.value=false;
 try{const result=await recycleNative.preview(props.input.kind==='knowledge'?{...props.input,scope:subtree.value?'subtree':'node'}:props.input);if(current===generation)view.value=result;}catch(e){if(current===generation)error.value=String(e);}finally{if(current===generation)busy.value=false;}}
async function open(event:MouseEvent){origin=event.currentTarget as HTMLElement;subtree.value=false;await nextTick();dialog.value?.showModal();dialog.value?.querySelector<HTMLButtonElement>('[data-cancel]')?.focus();await preview();}
async function execute(){if(busy.value||(!pending.value&&(!confirmed.value||!view.value?.previewToken)))return;
 pending.value??={requestId:crypto.randomUUID(),payload:{previewToken:view.value!.previewToken!,confirmation:'永久删除并销毁所选对象历史'}};busy.value=true;error.value='';
 try{await recycleNative.purge(pending.value.payload,pending.value.requestId);pending.value=null;busy.value=false;close();emit('changed');}
 catch(e){if((e as {definitive?:boolean}).definitive){pending.value=null;view.value=undefined;confirmed.value=false;}error.value=String(e);}finally{busy.value=false;}}
watch(()=>props.input,()=>{if(!canClose())return;generation++;view.value=undefined;error.value='';dialog.value?.close();},{deep:true});onBeforeUnmount(()=>generation++);
defineExpose({close:()=>canClose()&&!dialog.value?.open});
</script>
<template><span class="recycle-impact-entry"><button type="button" :disabled="disabled||busy||!!pending" @click="open">永久删除范围与保护预览</button><Teleport to=".unified-shell"><dialog ref="dialog" class="recycle-impact-dialog" aria-label="原生永久删除范围预览" @cancel.prevent="close"><header><h2>永久删除</h2></header>
<p class="impact-notice">确认后将销毁所选对象及其自身历史，无法恢复。既有备份不会自动追溯删除。图片文件保守保留，不会误删共享资源。</p>
<label v-if="input.kind==='knowledge'"><input type="checkbox" aria-label="同时永久删除整棵知识子树" v-model="subtree" :disabled="busy||!!pending" @change="preview"/>同时删除整棵子树（默认仅所选知识点，下级保留并重新挂载）</label>
<p v-if="input.kind==='knowledge'">关联卡片的正文、答案、解析、复盘历史、评分与调度完整保留，仅解除被删知识点的关联。</p>
<p v-if="busy" role="status">正在核对或保存…</p><p v-if="error" role="alert">{{error}}</p>
<template v-if="view"><dl class="impact-counts"><template v-for="(label,key) in {cards:'统一卡片',knowledge:'知识点',versions:'发布版本',cycles:'学习周期',events:'学习事件',drafts:'卡片草稿',newDrafts:'未发布草稿',schedules:'排期记录',sessions:'复盘页面',referenceDocuments:'引用及回执记录',imageReferences:'图片身份引用'}" :key="key"><dt>{{label}}</dt><dd>{{view.counts[key]}}</dd></template></dl>
<p v-if="view.kind==='knowledge'">保留当前卡片集 {{view.preservedCards}} 张卡片。</p><details open><summary>实际删除对象（{{view.objects.length}}）</summary><ul class="impact-objects"><li v-for="object in view.objects" :key="object.kind+object.id"><strong>{{object.label||'未命名'}}</strong><small>{{{card:'卡片',deck:'卡片集',knowledge:'知识点',draft:'未发布草稿'}[object.kind]}} · 修订 {{object.revision}} · {{object.id}}</small></li></ul></details>
<details><summary>关联记录处理范围</summary><p v-for="effect in view.effects" :key="effect.table">{{effectLabels[effect.table]??'关联维护记录'}}：删除 {{effect.deleted}}，更新 {{effect.updated}}，保留恢复记录 {{effect.created}}</p></details>
<section v-if="view.blockers.length" aria-label="永久删除阻断原因"><h3>当前保护条件</h3><p v-for="reason in view.blockers" :key="reason">{{reason}}</p></section>
<label v-if="view.execution==='ready'"><input type="checkbox" aria-label="确认销毁所选对象及其历史" v-model="confirmed" :disabled="busy||!!pending"/>我确认永久删除以上对象及其自身历史，无法撤销。</label><p class="impact-fingerprint">数据代次 {{view.epoch}}<br/>范围指纹 {{view.fingerprint}}</p></template>
<footer><button type="button" data-cancel :disabled="busy||!!pending" @click="close">取消</button><button v-if="error&&!pending" type="button" :disabled="busy" @click="preview">重新核对范围</button><button type="button" :disabled="busy||(!pending&&(!confirmed||view?.execution!=='ready'))" @click="execute">{{pending?'核对原永久删除请求':'确认永久删除'}}</button></footer></dialog></Teleport></span></template>
<style scoped>.recycle-impact-entry{display:inline-block}.recycle-impact-dialog{box-sizing:border-box;width:min(720px,calc(100vw - 40px));max-height:85vh;overflow:auto;border:1px solid var(--border);border-radius:13px;padding:22px;background:var(--surface);color:var(--ink)}.recycle-impact-dialog::backdrop{background:#14291e66}.recycle-impact-dialog:not([open]){display:none}h2{font-size:18px;margin:0 0 14px}h3{font-size:13px}.impact-notice{padding:12px;border-radius:8px;background:var(--soft);font-size:12px}.impact-counts{display:grid;grid-template-columns:1fr auto 1fr auto;gap:8px 14px;font-size:12px;margin:16px 0}dd{margin:0;color:var(--primary);font-weight:700}.impact-objects{max-height:180px;overflow:auto;list-style:none;padding:0;font-size:12px}.impact-objects li{padding:8px 0;border-bottom:1px solid var(--border)}.impact-objects small{display:block;color:var(--muted);font-size:10px;overflow-wrap:anywhere}section p{font-size:12px;line-height:1.7;padding:10px;background:#fff7ed;border-radius:7px}.impact-fingerprint{color:var(--muted);font-size:10px;overflow-wrap:anywhere}footer{display:flex;justify-content:flex-end;gap:8px;position:sticky;bottom:-22px;background:var(--surface);padding:14px 0}summary{cursor:pointer;font-size:12px}@media(max-width:610px){.impact-counts{grid-template-columns:1fr auto}}</style>
